// spec: .qa/e2e/specs/navigation.md (3.1)
// seed: tests/seed.new4.spec.ts
import { test, expect } from '@playwright/test';
import path from 'node:path';

test.use({ storageState: path.join(__dirname, '../../../auth/new4.json') });

test.describe('Навигация — пустые состояния', () => {
  test('Пустой экран «ילדים» = Figma 04.3: «עוד אין ילדים», «יצירת כרטיס» 56/18, без «+» #fb3b8d53 @iphone @prod-safe', async ({ page }) => {
    // 1. /home → таб «ילדים» → /children
    await page.goto('/home');
    await page.getByRole('tab', { name: 'ילדים' }).filter({ visible: true }).click();
    await expect(page).toHaveURL(/\/children/);

    // 2. Пустое состояние
    const title = page.getByRole('heading', { name: 'עוד אין ילדים' }).filter({ visible: true });
    await expect(title).toBeVisible();
    await expect(page.getByText('כרטיס עוזר ל-Banci לזהות מי בבריכה.').filter({ visible: true })).toBeVisible();

    // Иллюстрация над заголовком
    const pic = page.getByRole('img').filter({ visible: true }).filter({ hasNot: page.getByRole('tab') });
    const titleBox = (await title.boundingBox())!;
    const above = await pic.evaluateAll((els, top) => els.some((e) => {
      const r = e.getBoundingClientRect();
      // Рамка картинки может быть выше самого рисунка — проверяем верх и центр рисунка над заголовком.
      return r.height > 40 && r.top < top && r.top + r.height / 2 < top;
    }), titleBox.y);
    expect(above, 'иллюстрация над «עוד אין ילדים»').toBe(true);

    // Кнопка «יצירת כרטיס»: высота 56 ±1, шрифт подписи 18 (Figma 04.3). Не нажимать.
    const create = page.getByRole('button', { name: 'יצירת כרטיס', exact: true }).filter({ visible: true });
    await expect(create).toBeVisible();
    const box = (await create.boundingBox())!;
    expect(Math.abs(box.height - 56), `высота кнопки ${box.height}`).toBeLessThanOrEqual(1);
    const font = await create.evaluate((el) => {
      const t = [...el.querySelectorAll('*')].find((n) => n.childElementCount === 0 && n.textContent?.trim() === 'יצירת כרטיס') ?? el;
      return parseFloat(getComputedStyle(t as Element).fontSize);
    });
    expect(font).toBe(18);

    // Нет кнопки «+» (הוספת ילד) на пустом экране
    await expect(page.getByRole('button', { name: 'הוספת ילד' }).filter({ visible: true })).toHaveCount(0);
    await expect(page.getByText('+', { exact: true }).filter({ visible: true })).toHaveCount(0);
  });
});
